const contentTypes = {
  ".css": "text/css; charset=utf-8",
  ".html": "text/html; charset=utf-8",
  ".js": "text/javascript; charset=utf-8",
  ".webp": "image/webp",
  ".jpg": "image/jpeg",
  ".jpeg": "image/jpeg",
  ".png": "image/png",
  ".woff2": "font/woff2",
};

const files = {"/index.html":"","/solutions.html":"","/about.html":"","/contact.html":"","/separation-kernel-hypervisor.html":"","/globe.html":"","/iot-solutions.html":"","/cybersecurity-solutions.html":"","/cybersecurity-visual.html":"","/iot-visual.html":"","/information-security-consulting.html":"","/consulting-visual.html":"","/styles.css":"","/service-page.css":"","/main.js":"","/why-globe.js":"","/service-page.js":"","/footer-mount.js":"","/CurvedInput.js":"ZXhwb3J0IHsgZGVmYXVsdCB9IGZyb20gJy4vY29tcG9uZW50cy9DdXJ2ZWRJbnB1dC5qcyc7Cg==","/components/CurvedInput.js":"","/components/CurvedInput.jsx":"","/components/CurvedInput.css":"","/assets/logo.webp":"","/assets/solution-kernel.jpg":"","/assets/solution-iot.jpg":"","/assets/solution-cybersecurity.jpg":"","/assets/solution-consulting.jpg":""};

export default {
  async fetch(request) {
    const url = new URL(request.url);
    const pathname = url.pathname === "/" ? "/index.html" : url.pathname;
    const asset = files[pathname];

    if (!asset) {
      return new Response("Not found", { status: 404 });
    }

    const extension = pathname.slice(pathname.lastIndexOf("."));
    return new Response(Uint8Array.from(atob(asset), (character) => character.charCodeAt(0)), {
      headers: {
        "Cache-Control": pathname === "/index.html" ? "no-cache" : "public, max-age=31536000, immutable",
        "Content-Type": contentTypes[extension] || "application/octet-stream",
      },
    });
  },
};
